scripts.onUpdate:
const config = api.read.data() || {};
const state = component.state || (component.state = {});
const components = api.read.components || {};
const cols = Number(config.columns || 12);
const rows = Number(config.rows || 15);
const radius = Number(config.radius || 0.9);
const cellHeight = Number(config.cellHeight || 0.39);
const baseRadius = Number(config.baseRadius || 0.98);
const baseSegments = Number(config.baseSegments || 24);
const baseY = Number(config.baseY || -3.02);
const palette = config.palette || {
  empty: [0.055, 0.075, 0.11, 0],
  ghost: [0.60, 0.74, 0.67, 0.42],
  I: [0.19, 0.82, 0.96, 1],
  J: [0.25, 0.43, 0.96, 1],
  L: [0.97, 0.56, 0.18, 1],
  O: [0.98, 0.82, 0.20, 1],
  S: [0.24, 0.78, 0.42, 1],
  T: [0.67, 0.39, 0.96, 1],
  Z: [0.94, 0.30, 0.34, 1],
  warning: [1.0, 0.22, 0.22, 1]
};
const shapes = config.shapes || {
  I: [[0,1],[1,1],[2,1],[3,1]],
  J: [[0,0],[0,1],[1,1],[2,1]],
  L: [[2,0],[0,1],[1,1],[2,1]],
  O: [[1,0],[2,0],[1,1],[2,1]],
  S: [[1,0],[2,0],[0,1],[1,1]],
  T: [[1,0],[0,1],[1,1],[2,1]],
  Z: [[0,0],[1,0],[1,1],[2,1]]
};
const kinds = config.kinds || ['I','J','L','O','S','T','Z'];
const scoreByLines = [0, 100, 300, 500, 800];

function mod(value, size) {
  return ((value % size) + size) % size;
}

function colorOf(value) {
  if (!value) return palette.empty;
  return palette[value] || palette.T;
}

function setColor(material, color) {
  if (!material || !material.color || !material.color.set) return;
  material.color.set(color[0], color[1], color[2], color[3] == null ? 1 : color[3]);
}

function getComponent(entity, name) {
  const direct = entity && entity.getComponent && entity.getComponent(name);
  if (direct) return direct;
  for (const item of entity && entity.components && entity.components.values ? entity.components.values() : []) {
    if (item && (item.name === name || String(item.UniqueSymbol) === 'Symbol(' + name + ')')) return item;
  }
  return null;
}

function getCellEntity(column, row) {
  const index = row * cols + column;
  return api.read && api.read.find('Cylinder Cell ' + index);
}

function cloneGrid() {
  return Array.from({ length: rows }, function () { return Array(cols).fill(''); });
}

function randomKind() {
  return kinds[Math.floor(Math.random() * kinds.length)] || 'T';
}

function makePiece(kind) {
  return { kind: kind, x: Math.floor(cols / 2) - 2, y: 0, r: 0 };
}

function rotatedLocalCells(piece) {
  const source = shapes[piece.kind] || shapes.T;
  return source.map(function (point) {
    let px = point[0];
    let py = point[1];
    for (let i = 0; i < piece.r % 4; i++) {
      const nextX = 3 - py;
      py = px;
      px = nextX;
    }
    return { x: px, y: py };
  });
}

function cells(piece) {
  return rotatedLocalCells(piece).map(function (cell) {
    return { x: mod(piece.x + cell.x, cols), y: piece.y + cell.y, kind: piece.kind };
  });
}

function collides(piece) {
  const seen = new Set();
  for (const cell of cells(piece)) {
    const key = cell.x + ',' + cell.y;
    if (seen.has(key)) return true;
    seen.add(key);
    if (cell.y >= rows) return true;
    if (cell.y >= 0 && state.grid[cell.y][cell.x]) return true;
  }
  return false;
}

function pieceCenterColumn(piece) {
  const local = rotatedLocalCells(piece);
  const sum = local.reduce(function (total, cell) { return total + cell.x; }, 0);
  return mod(piece.x + sum / Math.max(1, local.length), cols);
}

function focusCurrentPiece() {
  if (!state.current) return;
  state.viewColumnTarget = pieceCenterColumn(state.current);
}

function spawn() {
  state.current = makePiece(state.next || randomKind());
  state.next = randomKind();
  focusCurrentPiece();
  if (collides(state.current)) state.phase = 'gameover';
}

function reset() {
  state.grid = cloneGrid();
  state.current = makePiece(randomKind());
  state.next = randomKind();
  state.score = 0;
  state.lines = 0;
  state.level = 1;
  state.drop = 0;
  state.phase = 'playing';
  state.viewColumn = pieceCenterColumn(state.current);
  state.viewColumnTarget = state.viewColumn;
  if (collides(state.current)) state.phase = 'gameover';
}

function move(dx, dy) {
  const next = { ...state.current, x: mod(state.current.x + dx, cols), y: state.current.y + dy };
  if (collides(next)) return false;
  state.current = next;
  if (dx) focusCurrentPiece();
  return true;
}

function rotate(dir) {
  const next = { ...state.current, r: mod(state.current.r + dir, 4) };
  const kicks = [0, -1, 1, -2, 2];
  for (const kick of kicks) {
    const kicked = { ...next, x: mod(next.x + kick, cols) };
    if (!collides(kicked)) {
      state.current = kicked;
      focusCurrentPiece();
      return;
    }
  }
}

function lock() {
  for (const cell of cells(state.current)) {
    if (cell.y >= 0 && cell.y < rows) state.grid[cell.y][cell.x] = state.current.kind;
  }
  let cleared = 0;
  state.grid = state.grid.filter(function (row) {
    const full = row.every(Boolean);
    if (full) cleared++;
    return !full;
  });
  while (state.grid.length < rows) state.grid.unshift(Array(cols).fill(''));
  if (cleared) {
    state.lines += cleared;
    state.level = Math.floor(state.lines / 10) + 1;
    state.score += (scoreByLines[cleared] || cleared * 200) * state.level;
  }
  spawn();
}

function hardDrop() {
  while (move(0, 1)) state.score += 2;
  lock();
}

function shortestColumnDelta(target, current) {
  let delta = target - current;
  while (delta > cols / 2) delta -= cols;
  while (delta < -cols / 2) delta += cols;
  return delta;
}

function visibleValues() {
  const values = state.grid.map(function (row) { return row.slice(); });
  if (state.phase !== 'gameover') {
    for (const cell of cells(state.current)) {
      if (cell.y >= 0 && cell.y < rows) values[cell.y][cell.x] = cell.kind;
    }
  }
  return values;
}

function updateCamera() {
  const camera = api.read && api.read.find('Cylinder Camera');
  const spherical = getComponent(camera, 'SphericalTransform3D');
  if (!spherical) return;
  const canvas = document.getElementById('player-canvas');
  const width = Math.max(1, canvas && canvas.clientWidth || window.innerWidth || 1280);
  const height = Math.max(1, canvas && canvas.clientHeight || window.innerHeight || 720);
  const portrait = height >= width;
  spherical.radius = portrait ? 7.2 : 6.4;
  spherical.phi = portrait ? 1.14 : 1.20;
  spherical.theta = Math.PI;
  if (spherical.setTarget) spherical.setTarget(0, -0.15, 0);
}

function updateHud() {
  api.scene && api.scene.setText('Cylinder Tetris Score', 'Score ' + state.score + '\nLines ' + state.lines + '\nLevel ' + state.level);
  api.scene && api.scene.setText('Cylinder Tetris Next', 'Next\n' + state.next);
  const status = state.phase === 'playing' ? 'Cylinder 12 x 15\nLeft / Right rotate' : state.phase === 'paused' ? 'Paused' : 'Game Over\nPress R';
  api.scene && api.scene.setText('Cylinder Tetris Status', status);
}

function updateBaseRing() {
  const segments = baseSegments;
  const step = Math.PI * 2 / segments;
  for (let i = 0; i < segments; i++) {
    const entity = api.read && api.read.find('Cylinder Base Ring ' + i);
    if (!entity) continue;
    const transform = getComponent(entity, 'CartesianTransform3D');
    if (!transform) continue;
    const angle = Math.PI + (i / segments * cols - state.viewColumn) * (Math.PI * 2 / cols);
    const px = Math.sin(angle) * baseRadius;
    const pz = Math.cos(angle) * baseRadius;
    transform.setPosition(px, baseY, pz);
    transform.setRotation(0, angle, 0);
    transform.setScale(1.05, 0.22, 0.32);
  }
}

function draw(delta) {
  updateCamera();
  const target = Number.isFinite(state.viewColumnTarget) ? state.viewColumnTarget : state.current.x;
  const speed = Math.min(1, Math.max(0.12, delta / 90));
  state.viewColumn += shortestColumnDelta(target, state.viewColumn) * speed;
  state.viewColumn = mod(state.viewColumn, cols);

  const values = visibleValues();
  const step = Math.PI * 2 / cols;
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      const entity = getCellEntity(x, y);
      if (!entity) continue;
      const transform = getComponent(entity, 'CartesianTransform3D');
      const mesh = getComponent(entity, 'Mesh3D');
      const value = values[y][x];
      const displayColumn = x - state.viewColumn;
      const angle = Math.PI + displayColumn * step;
      const radial = radius;
      const px = Math.sin(angle) * radial;
      const pz = Math.cos(angle) * radial;
      const py = (rows / 2 - y - 0.5) * cellHeight;
      entity.disabled = !value;
      if (transform) {
        transform.setPosition(px, py, pz);
        transform.setRotation(0, angle, 0);
        transform.setScale(1, 1, 1);
      }
      if (mesh) setColor(mesh.material, value ? colorOf(value) : palette.empty);
    }
  }
  updateBaseRing();
  updateHud();
}

if (!state.ready) {
  reset();
  state.ready = true;
  api.debug.console.log('Cylinder Tetris 3D ready.');
}

if (api.input.wasPressed('Restart') || api.input.wasPressed('KeyR')) reset();
if (api.input.wasPressed('Pause') || api.input.wasPressed('KeyP')) state.phase = state.phase === 'paused' ? 'playing' : state.phase === 'playing' ? 'paused' : state.phase;

if (state.phase === 'playing') {
  if (api.input.wasPressed('MoveLeft')) move(-1, 0);
  if (api.input.wasPressed('MoveRight')) move(1, 0);
  if (api.input.wasPressed('Rotate') || api.input.wasPressed('RotateCW')) rotate(1);
  if (api.input.wasPressed('RotateCCW')) rotate(-1);
  if (api.input.wasPressed('HardDrop')) hardDrop();
  state.drop += delta * (api.input.isPressed('SoftDrop') ? 12 : 1);
  const interval = Math.max(115, Number(config.dropMs || 680) - (state.level - 1) * 42);
  if (state.drop >= interval) {
    state.drop = 0;
    if (!move(0, 1)) lock();
  }
}

draw(delta);
